import math

def get_divisors_and_multiples(n, limit=100):
    """Generates divisors and multiples of n, greater than 1, up to a limit."""
    ds = set()
    ms = set()

    # Divisors
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            ds.add(i)
            ds.add(n // i)
    if n >= 2:
        ds.add(n) # n itself is a divisor

    # Multiples
    for i in range(2, limit // n + 1):
        ms.add(i * n)

    return list(ds | ms)

